import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"風地觀","description":"周易折中 - 風地觀","frontmatter":{"title":"風地觀","description":"周易折中 - 風地觀"},"headers":[],"relativePath":"classics/zhezhong/026.md","filePath":"classics/zhezhong/026.md"}'),h={name:"classics/zhezhong/026.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="風地觀" tabindex="-1">風地觀 <a class="header-anchor" href="#風地觀" aria-label="Permalink to “風地觀”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>觀序卦：臨者大也，物大然後可觀，故受之以觀。觀所以次臨也。凡觀視於物，則為觀；為觀於下，則為觀，如樓觀謂之觀者，為觀於下也。人君上觀天道，下觀民俗，則為觀；修德行政，為民瞻仰，則為觀。風行地上，遍觸萬類，周觀之象也。二陽在上，四陰在下，陽剛居尊，為群下所觀仰，觀之義也。在諸爻，則唯取觀見，隨時為義也。</p><p>觀：盥而不薦，有孚顒若</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>觀者有以示人而為人所仰也。九五居上，四陰仰之，又內順外巽，而九五以中正示天下，所以為觀。盥，將祭而潔手也；薦，奉酒食以祭也。顒然，尊敬之貌。言致其潔清而不輕自用，則其孚信在中而顒然可仰。戒佔者宜如是也。或曰有孚顒若，謂在下之人信而仰之也。此卦四陰長而二陽消，正為八月之卦，而名卦繋辭更取他義，亦扶陽抑陰之意。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>予聞之胡翼之先生曰：君子居上為天下之表儀，必極其莊敬，則下觀仰而化也。故為天下之觀，當如宗廟之祭，始盥之時，不可如既薦之後，則下民盡其至誠，顒然瞻仰之矣。盥謂祭祀之始，盥手酌鬱鬯於地求神之時也；薦謂獻腥獻熟之時也。盥者事之始，人心方盡其精誠，嚴肅之至也；至既薦之後，禮數繁縟，則人心散而精一不若始盥之時矣。居上者正其表儀以為下民之觀，當莊嚴如始盥之初，勿使誠意少散如既薦之後，則天下之人莫不盡其孚誠，顒然瞻仰之矣。顒，仰望也。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>朱子語類雲：自上示下曰觀，自下觀上曰觀，故卦名之“觀”去聲，而六爻之“觀”皆平聲。 或問：伊川以為灌鬯之初，誠意猶存，至薦羞之後，精意懈怠；本義以為致其潔清而不輕自用，其義不同。 曰：盥只是浣手，不是灌鬯。伊川承先儒之誤。若雲薦羞之後，誠意懈怠，則先王祭祀只是灌鬯之初猶有誠意，及薦羞之後皆不成禮矣。問若爾，則是聖人在上，視聽言動皆當為天下法而不敢輕，亦猶祭祀之時致其潔清而不敢輕用否？曰然。 又云：祭祀無不薦者，此是假設來說。薦是用事了，盥是未用事之初。雲“不薦”者，言常持得這誠敬如盥之意常在。若薦則是用出，用出則才畢便過了，無復有初意矣。 問：“有孚顒若”承上文“盥而不薦”，蓋致其潔清而不輕自用，則孚信在中而顒然可仰。一說下之人信而仰之。二說孰長？曰從後說則合得彖辭“下觀而化”之義。問前說似好？ 曰：當以彖辭為定。</p></li><li><p>自上示下曰觀，自下觀上曰觀，故卦名之“觀”去聲，而六爻之“觀”皆平聲。</p></li><li><p>或問：伊川以為灌鬯之初，誠意猶存，至薦羞之後，精意懈怠；本義以為致其潔清而不輕自用，其義不同。 曰：盥只是浣手，不是灌鬯。伊川承先儒之誤。若雲薦羞之後，誠意懈怠，則先王祭祀只是灌鬯之初猶有誠意，及薦羞之後皆不成禮矣。問若爾，則是聖人在上，視聽言動皆當為天下法而不敢輕，亦猶祭祀之時致其潔清而不敢輕用否？曰然。</p></li><li><p>又云：祭祀無不薦者，此是假設來說。薦是用事了，盥是未用事之初。雲“不薦”者，言常持得這誠敬如盥之意常在。若薦則是用出，用出則才畢便過了，無復有初意矣。</p></li><li><p>問：“有孚顒若”承上文“盥而不薦”，蓋致其潔清而不輕自用，則孚信在中而顒然可仰。一說下之人信而仰之。二說孰長？曰從後說則合得彖辭“下觀而化”之義。問前說似好？ 曰：當以彖辭為定。</p></li><li><p>馮氏椅曰：卦疊艮之畫，有門闕重複之象，故取象於觀。</p></li><li><p>龔氏煥曰：易之名卦以陽為主，在陽長之卦固主於陽而言，在陰長之卦亦主於陽而言。主於陽而言者，所以扶陽也。此四陰之卦不曰“小壯”而曰“觀”也。四陽之卦有曰“大過”，四陰之卦有曰“小過”者，何陰可以言過而不可以言壯也？然大過之四陽過而居中，小過之四陰過而居外，亦崇陽抑陰之意。</p></li><li><p>梁氏寅曰：“盥而不薦”，設辭以見其潔清之至而不輕自用耳，猶中庸曰“不動而敬，不言而信”。聖人未嘗不言不動也，而其敬其信則尤在於未言動之時。故聖人之御天下也，其政教之施民固無不化矣，而其政教未施之時，所以化民者尤有不言之妙焉。蓋其篤恭之極，如臨大祭而孚誠之念存於中，顒然之容見於外，故下民之望之也，其信從化服自有不知其然矣。</p></li><li><p>蔡氏清曰：平庵項氏雲此但以“盥而不薦”象“恭己無為”耳。愚謂“恭己”二字則說得，“無為”二字難通。無為者，聖人德盛而民自化，不待有所為，非不輕自用意也。無為豈可用心乎？雖堯舜亦不能自期於無為。至於神道設教而天下服，則是觀之極致，聖人之能事，是則所謂“無為”者。</p></li><li><p>林氏希元曰：“盥將以薦”，豈有不薦之理？曰：“盥而不薦”，特以明敬常在之意耳。“盥而不薦”就祭祀上說，“有孚顒若”亦是就祭祀上說。為“觀”之意，則在言表。</p></li></ul><p>象曰：風行地上，觀；先王以省方觀民設教</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>省方以觀民設教，以為觀。</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>風行地上，周及庶物，為遨歷周覽之象。故先王體之為省方之禮，以觀民俗而設政教也。天子巡省四方，觀視民俗，設為政教，如奢則約之以儉，儉則示之以禮是也。省方觀民也，設教為民觀也。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li>九家易曰：風行地上，草木必偃，故以省察四方，觀視民俗而設其教也。○劉氏牧曰：風行地上，無所不至，散採萬國之聲詩，省察其俗有不同者，教之使同。</li></ul><p>彖曰：大觀在上，順而巽，中正以觀天下</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>以卦體卦德釋卦名義。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>五居尊位，以剛陽中正之德為下所觀，其德甚大，故曰“大觀在上”。下坤而上巽，是能順而巽也。五居中正，以巽順中正之德為觀於天下也。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>趙氏彥肅曰：“大觀在上”，統謂二陽中正以觀天下。</p></li><li><p>楊氏啟新曰：“順以宅心”，堯舜之溫恭克讓，文王之徽柔懿恭是也；“巽以制事”，通人情、酌物理、隨物付物、因時制宜者也。巽德之制也，非巽何以使萬事各得其宜。</p></li></ul><p>觀盥而不薦，有孚顒若，下觀而化也</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>釋卦辭。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>為觀之道，嚴敬如始盥之時，則下民至誠瞻仰而從化也。“不薦”，謂不使誠意少散也。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>虞氏翻曰：“孚”信，“顒”有威，“容”容貌，“容止可觀，進退可度”，則下觀其德而順其化。《詩》曰：“顒顒卬卬，如圭如璋”，君德之義也。</p></li><li><p>朱氏震曰：祭之初，迎屍入廟，天子盥手而後酌酒。盥謂之盥，酌酒獻屍，屍得之灌地而祭謂之祼。祼之後三獻而薦腥，五獻而薦熟，謂之薦。盥者，未祼之時，精神專一，誠意未散，不言之信發而為敬順之貌，顒顒如也。故下觀而化，莫不有敬順之心也。</p></li><li><p>王氏申子曰：觀示天下之道，其誠意精一，常如始盥之時，則觀感之下莫不從化。蓋有不動而敬、不言而信之妙。</p></li></ul><p>觀天之神道而四時不忒，聖人以神道設教而天下服矣</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>極言觀之道也。四時不忒，天之所以為觀也；神道設教，聖人之所以為觀也。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>天道至神，故曰神道。觀天之運行，四時無有差忒，則見其神妙。聖人見天道之神，體神道以設教，故天下莫不服也。夫天道至神，故運行四時化育萬物無有差忒。至神之道莫可名言，唯聖人黙契體其妙用，設為政教。故天下之人涵泳其德而不知其功，鼓舞其化而莫測其用，自然仰觀而戴服。故曰“以神道設教而天下服矣”。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>虞氏翻曰：聖人退藏於密，以神明其德，故設教而天下服矣。</p></li><li><p>王氏弼曰：統說觀之為道，不以刑制使物，而以觀感化物。神則無形者也，不見天之使四時而四時不忒，不見聖人使百姓而百姓自服也。</p></li><li><p>楊氏時曰：古人所以交神而接人，其道一主於誠。故曰“明則有禮樂，幽則有鬼神”。幽明本無二理，故所以感之者一。聖人以神道設教，所謂神道，誠意而已。誠意，天德也。</p></li><li><p>朱子語類雲：聖人以神道設教，即是“盥而不薦”之義。又云，天之神道只是自然運行底道理，四時自然不忒；聖人神道亦是有教人自然觀感處。</p></li><li><p>呉氏澄曰：常人以言設教，則有聲音；以身設教，則有形跡。聖人妙天道於不測，其應捷如影響。蓋所存者神，故所過者化也。</p></li><li><p>楊氏啟新曰：聖人設教，誠於此而動於彼，不顯之德、篤恭之妙，與上天之載無聲無臭者同一機。而其動物之妙、丕變之感，有非人所能測者。故曰“神道設教”。</p></li></ul><p>初六：童觀，小人無咎，君子吝</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>卦以觀示為義，據九五為主也。爻以觀瞻為義，皆觀乎九五也。初六陰柔在下，不能遠見，童觀之象。小人之道，君子之羞也。故其佔在小人則無咎，君子得之則可羞矣。</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>六以陰柔之質，居遠於陽，是以觀見者淺近如童稚然，故曰童觀。陽剛中正在上，聖賢之君也。近之則見其道德之盛，所觀深遠。初乃遠之所見，不明如童蒙之觀也。小人下民也，所見昏淺，不能識君子之道，乃常分也，不足謂之過咎。若君子而如是，則可鄙吝也。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏弼曰 ：觀之為義，以所見為美者也，故以近尊為尚，遠之為吝。</li></ul><p>象曰：初六童觀，小人道也</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>所觀不明，如童稚，乃小人之分，故曰小人道也。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏申子曰：卑下而無遠見，在凡民為可恕，在君子為可羞。</li></ul><p>六二：窺觀，利女貞</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>陰柔居內而觀乎外，窺觀之象。女子之正也，故其佔如此。丈夫得之則非所利矣。</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>二應於五，觀於五也。五剛陽中正之道，非二陰暗柔弱所能觀見也，故但如窺覘之觀耳。窺覘之觀雖少見而不能甚明也。二既不能明見剛陽中正之道，則利如女子之貞，雖見之不能甚明而能順從者，女子之道也。在女子為貞也。二既不能明見九五之道，能如女子之順從，則不失中正，乃為利也。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li>胡氏炳文曰 ：初位陽，故為童；二位陰，故為女。童觀是茫然無所見，小人日用而不知者也。窺觀是所見者小而不見全體也。佔曰“利女貞”，則非丈夫之所為可知矣。</li></ul><p>象曰：窺觀，女貞，亦可醜也</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>在丈夫則為醜也。</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>君子不能觀見剛陽中正之大道，而僅窺覘其彷彿，雖能順從，乃同女子之貞，亦可羞醜也。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li>郭氏忠孝曰：男女吉凶不同，故恆卦曰“婦人吉，夫子兇”，則知利女貞者固為男之醜也。</li></ul><p>六三：觀我生，進退</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>我生，我之所行也。六三居下之上，可進可退，故不觀九五而獨觀己所行之通塞，以為進退。佔者宜自審也。</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>三居非其位，處順之極，能順時以進退者也。若居當其位，則無進退之義也。觀我生，我之所生謂動作施為出於己者，觀其所生而隨宜進退，所以處雖非正而未至失道也。隨時進退，求不失道，故無悔咎，以能順也。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎達曰 ：三居下體之極，是有可進之時；又居上體之下，復是可退之地。遠則不為童觀，近則未為觀國，居在進退之處，可以自觀時。可則進，時不可則退，故曰“觀我生進退”也。</p></li><li><p>劉氏牧曰 ：自觀其道，應於時則進，不應於時則退。</p></li><li><p>朱子語類雲 ：六三之“觀我生進退”者，事君則觀其言聽計從，治民則觀其政教可行，膏澤可下，可以見自家所施之當否而為進退。</p></li><li><p>王氏申子曰 ：三處下之上，上之下，故有進退之象。君子進退常觀乎時，今不觀乎時而觀我生者，蓋九五方以陽剛中正觀示天下，則時不待觀也，但觀吾之所有以為進退可也。</p></li><li><p>胡氏炳文曰 ：他卦三不中多不善，二居中多善，而觀以遠近為義，故如此。諸爻皆欲觀五，惟近者得之。六四最近，故可決於進；六三上下之間，可進可退之地，故不必觀五，但觀我所為而為之進退。本義謂佔者宜自審，蓋當進退之際，惟當自審其所為何如耳。</p></li></ul><p>象曰：觀我生，進退未失道也</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>觀己之生而進退以順乎宜，故未至於失道也。</p><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>道即進退之道，量而後入，則不失乎進退之道矣。</p><p>六四：觀國之光，利用賓於王</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>六四最近於五，故有此象。其佔為利於朝覲仕進也。</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>觀莫明於近五。以陽剛中正居尊位，聖賢之君也。四切近之，觀見其道，故云“觀國之光”。觀見國之盛德光輝也。不指君之身而云國者，在人君而言，豈止觀其行一身乎？當觀天下之政化，則人君之道德可見矣。四雖陰柔而巽體居正，切近於五，觀見而能順從者也。利用賓於王，夫聖明在上，則懷抱才德之人皆願進於朝廷，輔戴之以匡濟天下。四既觀見人君之德，國家之治，光華盛美，所宜賓於王朝，效其智力，上輔於君以施澤天下，故云“利用賓於王”也。古者有賢德之人，則人君賓禮之，故士之仕進於王朝，則謂之賓。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li>劉氏定之曰 ：九五大君，觀己所為以儀型天下。初居陽而去五遠，所觀不明如童子；二居陰而去五遠，所觀不明如女子。惟四得正而去五近，所觀最明，故曰“觀光賓王”。蓋諸爻皆就五取義也。</li></ul><p>象曰：觀國之光，尚賓也</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>君子懷負才業，志在乎兼善天下。然有卷懷自守者，蓋時無明君，莫能用其道，不得已也，豈君子之志哉？故孟子曰：“中天下而立，定四海之民，君子樂之。”既觀見國之盛德光華，古人所謂非常之遇也，所以志願登進王朝以行其道，故云“觀國之光，尚賓也”。尚謂志尚，其志意願慕賓於王朝也。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li>楊氏簡曰：言其國貴尚賓賢，可以進也。</li></ul><p>九五：觀我生，君子無咎</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>九五陽剛中正以居尊位，其下四陰仰而觀之，君子之象也。故戒居此位得此佔者，當觀巳所行，必其陽剛中正亦如是焉，則得無咎也。</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>九五居人君之位，時之治亂，俗之美惡，系乎已而己。觀已之生，若天下之俗皆君子矣，則是已之所為政化善也，乃無咎矣。若天下之俗未合君子之道，則是已之所為政治未善，不能免於咎也。</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎達曰 ：九五居尊，為觀之主，四海之內由我而化。我教化善，則天下有君子之風；教化不善，則天下著小人之俗。故觀民以察我道，有君子之風者，則無咎也。</p></li><li><p>朱子語類雲 ：九五之“觀我生”，如觀風俗之美惡，臣民之從違，可以見自家所施之善惡。</p></li><li><p>王氏申子曰 ：五陽剛中正，居尊位以觀天下，此君子之道也。天下皆仰而觀之，在五又當觀巳之所行，必一齣於君子之道，然後可以立身於無過之地，故曰“觀我生，君子無咎”。</p></li></ul><p>象曰：觀我生，觀民也</p><h3 id="本義-11" tabindex="-1">本義 <a class="header-anchor" href="#本義-11" aria-label="Permalink to “本義”">​</a></h3><p>此夫子以義言之，明人君觀己所行，不但一身之得失，又當觀民德之善否以自省察也。</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>我生出於己者，人君欲觀己之施為善否，當觀於民。民俗善則政化善也。王弼雲：“觀民以察己之道是也。”</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li>胡氏瑗曰：觀流則可以知源，觀影則可以知表，觀民則可以知己政之得失也。</li></ul><p>上九：觀其生，君子無咎</p><h3 id="本義-12" tabindex="-1">本義 <a class="header-anchor" href="#本義-12" aria-label="Permalink to “本義”">​</a></h3><p>上九陽剛居尊位之上，雖不當事任而亦為下所觀，故其戒辭略與五同，但以我為其小有主賓之異耳。</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>上九以陽剛之德處於上，為下之所觀，而不當位，是賢人君子不在於位而道德為天下所觀仰者也。觀其生，觀其所生也，謂出於己者德業行義也。既為天下所觀仰，故自觀其所生，若皆君子矣，則無過咎也。苟未君子，則何以使人觀仰矜式，是其咎也。</p><h3 id="集說-14" tabindex="-1">集說 <a class="header-anchor" href="#集說-14" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏弼曰 ：觀我生，自觀其道者也；觀其生，為民所觀者也。不在於位，最處上極高尚，其志為天下所觀者也。處天下所觀之地，可不慎乎？故君子德見，乃得無咎。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>上九“觀其生”似只是承九五之義而終言之爾。蓋九五正當君位，故曰“我”。上非君位，而但以君道論之，故曰其辭與九五無異者，正所以見聖人省身察己始終如一之心。故象傳發明之曰：“志未平也。”</p><p>總論</p><ul><li><p>朱子語類 ：問：觀卦陰盛而不言兇咎。 曰：此卦取義不同。蓋陰雖盛於下，而九五之君乃當正位，故只取為觀於下之義，而不取陰盛之象也。 問：觀六爻，一爻勝似一爻，豈所居之位愈高則所見愈大耶？ 曰：上二爻意自別，下四爻是所據之位愈近則所見愈親切底意思。</p></li><li><p>問：觀卦陰盛而不言兇咎。 曰：此卦取義不同。蓋陰雖盛於下，而九五之君乃當正位，故只取為觀於下之義，而不取陰盛之象也。</p></li><li><p>問：觀六爻，一爻勝似一爻，豈所居之位愈高則所見愈大耶？ 曰：上二爻意自別，下四爻是所據之位愈近則所見愈親切底意思。</p></li></ul><p>象曰：觀其生，志未平也</p><h3 id="本義-13" tabindex="-1">本義 <a class="header-anchor" href="#本義-13" aria-label="Permalink to “本義”">​</a></h3><p>志未平，言雖不得位，未可忘戒懼也。</p><h3 id="程傳-17" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-17" aria-label="Permalink to “程傳”">​</a></h3><p>雖不在位，然以人觀其德用為儀法，故當自慎省。觀其所生常不失於君子，則人不失所望而化之矣。不可以不在於位，故安然放意無所事也。是其志意未得安也，故云“志未平也”。平謂安寧也。</p><h3 id="集說-15" tabindex="-1">集說 <a class="header-anchor" href="#集說-15" aria-label="Permalink to “集說”">​</a></h3><ul><li>陸氏希聲曰：民之善惡由我德化，其志未平，憂民之未化也。</li></ul>',120)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
